  "title": "Soma de Intervalos com Atualização Pontual",
  "contract_id": "extended_range_sum",
  "topic": "Segment Tree",
  "statement": {
    "description": "Dado um array de N inteiros, você deve processar Q operações. As operações podem ser de dois tipos: 1) Atualizar o valor de um elemento em uma posição específica; 2) Calcular a soma dos elementos em um intervalo [L, R].",
    "input": "A primeira linha contém dois inteiros N e Q. A segunda linha contém N inteiros representando o array inicial. As próximas Q linhas contêm cada uma uma operação: '1 K X' (atualiza a posição K para o valor X) ou '2 L R' (consulta a soma no intervalo [L, R]).",
    "output": "Para cada operação do tipo 2, imprima a soma do intervalo em uma nova linha.",
    "constraints": "1 ≤ N, Q ≤ 30000; valores iniciais e X entre 0 e 10^9. 1 ≤ L ≤ R ≤ N. Use inteiros de 64 bits (long long) para somas."
  },
  "reference_solution": {
    "code_cpp": "#include <iostream>
#include <vector>
using namespace std;

vector<long long> tree;
int n;

void update(int node, int start, int end, int idx, int val) {
    if (start == end) { tree[node] = val; return; }
    int mid = (start + end) / 2;
    if (idx <= mid) update(2 * node, start, mid, idx, val);
    else update(2 * node + 1, mid + 1, end, idx, val);
    tree[node] = tree[2 * node] + tree[2 * node + 1];
}

long long query(int node, int start, int end, int l, int r) {
    if (r < start || end < l) return 0;
    if (l <= start && end <= r) return tree[node];
    int mid = (start + end) / 2;
    return query(2 * node, start, mid, l, r) + query(2 * node + 1, mid + 1, end, l, r);
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int q; cin >> n >> q;
    tree.assign(4 * n + 1, 0);
    for (int i = 1; i <= n; ++i) { int val; cin >> val; update(1, 1, n, i, val); }
    while (q--) {
        int type; cin >> type;
        if (type == 1) { int k, x; cin >> k >> x; update(1, 1, n, k, x); }
        else { int l, r; cin >> l >> r; cout << query(1, 1, n, l, r) << "\n"; }
    }
    return 0;
}",
